package ec.edu.ucuenca.mda.vuelos.service;
import ec.edu.ucuenca.mda.vuelos.domain.*;
import ec.edu.ucuenca.mda.vuelos.dto.*;
import ec.edu.ucuenca.mda.vuelos.repository.*;
import ec.edu.ucuenca.mda.vuelos.support.*;
import java.time.*;
import java.util.*;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
@Transactional(readOnly=true)
public class AvionService {
    private final AvionRepository repository;
    private final AerolineaRepository aerolineaRepository;
    public AvionService(AvionRepository repository, AerolineaRepository aerolineaRepository) {
        this.repository = repository;
        this.aerolineaRepository = aerolineaRepository;
    }
    private AvionResponse response(Avion value) {
        return AvionResponse.from(value);
    }
    public AvionResponse get(Long id) { return response(repository.findById(id).orElseThrow(() -> BusinessException.notFound("Avion no encontrado"))); }
    public List<AvionResponse> list() { return repository.findAll(Sort.by("id")).stream().map(this::response).toList(); }
    @Transactional
    public AvionResponse create(AvionRequest request) {
        Aerolinea aerolinea = aerolineaRepository.findById(request.aerolineaId()).orElseThrow(() -> BusinessException.notFound("Aerolinea no encontrado"));
        Avion value = new Avion();
        value.setMatricula(request.matricula() == null ? null : request.matricula().trim().toUpperCase(Locale.ROOT));
        value.setCapacidad(request.capacidad());
        value.setAerolinea(aerolinea);
        return response(repository.saveAndFlush(value));
    }
}
